// copyTaskMetadataToV2 copies task metadata files (subagent transcripts, checkpoint JSONs)
// from the v1 branch to the v2 /full/current ref via tree surgery.
func copyTaskMetadataToV2(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, summary *checkpoint.CheckpointSummary) error {
	// Read the v1 checkpoint tree to find task subtrees
	v1Tree, err := v1Store.ReadCheckpointTree(ctx, cpID)
	if err != nil || v1Tree == nil {
		return err
	}

	// Look for tasks/ directory in each session
	for sessionIdx := range len(summary.Sessions) {
		sessionDir := fmt.Sprintf("%d", sessionIdx)
		sessionTree, sessionErr := v1Tree.Tree(sessionDir)
		if sessionErr != nil {
			continue
		}

		tasksTree, tasksErr := sessionTree.Tree("tasks")
		if tasksErr != nil {
			continue // No tasks directory in this session
		}

		// Splice the tasks tree into v2 /full/current at the same path
		if spliceErr := spliceTasksTreeToV2(repo, v2Store, cpID, sessionIdx, tasksTree.Hash); spliceErr != nil {
			return fmt.Errorf("session %d task tree splice failed: %w", sessionIdx, spliceErr)
		}
	}

	return nil
}

func spliceTasksTreeToV2(repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, sessionIdx int, tasksTreeHash plumbing.Hash) error {
	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
	parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
	if err != nil {
		return err
	}

	// Build path: <shard-prefix>/<shard-suffix>/<session-idx>/tasks
	shardPrefix := string(cpID[:2])
	shardSuffix := string(cpID[2:])
	sessionDir := fmt.Sprintf("%d", sessionIdx)

	newRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
		[]string{shardPrefix, shardSuffix, sessionDir},
		[]object.TreeEntry{
			{Name: "tasks", Mode: filemode.Dir, Hash: tasksTreeHash},
		},
		checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.MergeKeepExisting},
	)
	if err != nil {
		return fmt.Errorf("tree surgery failed: %w", err)
	}

	return v2Store.UpdateRefDirect(refName, newRoot, parentHash, "Add task metadata for "+string(cpID))
}
```

Note: This requires `ReadCheckpointTree` and `UpdateRefDirect` to be accessible. If `ReadCheckpointTree` doesn't exist, we'll need to build it from `getSessionsBranchTree` + tree traversal. If `UpdateRefDirect` doesn't exist, we'll use the existing `updateRef` or add a thin wrapper. These may need to be public methods or the migration can use the v1 store's internal tree access. Adjust based on what's actually exported.

**Important:** Check what's actually exported from the checkpoint package before implementing. The tree surgery approach may need to use `checkpoint.BuildTreeFromEntries` and `checkpoint.UpdateSubtree` (both already public), plus direct ref reading via `v2Store.GetRefState` (public). The `updateRef` method on `V2GitStore` is private — if needed, either:
- Add a public `UpdateRefDirect` method, or
- Use the `flattenCheckpointEntries` + `spliceCheckpointSubtree` pattern that `writeCommittedFullTranscript` uses

The exact implementation should match whatever is actually exported. If tree surgery proves too complex for this task, an alternative is to skip task metadata copying entirely and log a warning — the spec says task metadata is "copied via tree surgery" but the primary goal is metadata + transcript migration.

