	// Resolve the v1 branch tree
	v1Tree, err := resolveV1CheckpointTree(repo, cpID)
	if err != nil {
		return err
	}

	for sessionIdx := range len(summary.Sessions) {
		sessionDir := strconv.Itoa(sessionIdx)
		sessionTree, sessionErr := v1Tree.Tree(sessionDir)
		if sessionErr != nil {
			continue
